using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class SocialWorldTests
{
 internal static ContractWorld Start(string selected="created:social-a")
 {
  var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:social-a"),NewGameWorldTests.Officer("created:social-b")]);
  return NewGameWorld.Create(setup.World,setup.Registered,selected,42,NewGameWorld.CompactPersonalAuthority,null,null,LocalInspectionFindings.Policy,WorkFollowup.Policy);
 }
 static EntityId Other=new("created:social-b");
 static CommandResult Act(WorldSession s,SocialWorldAction action,EntityId? person=null,long amount=0,EntityId? reference=null,string? id=null)=>s.ManageSocial(new(new(id??"request:social/"+s.Revision),action,person??Other,Amount:amount,Reference:reference),s.Revision);
 [Fact]public void VisitCreatesDirectedFactsWithoutBuyingAuthority(){var s=new WorldSession(Start());Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.Visit).Code);var w=s.DiagnosticSnapshot();Assert.Single(SocialWorld.Facts(w,s.PlayerControl,Other));Assert.Single(SocialWorld.Facts(w,Other,s.PlayerControl));Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==Other);Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.Visit).Code);}
 [Fact]public void GiftMovesExistingCoinsExactlyOnceAfterLocalReceipt(){var s=new WorldSession(Start());var before=s.DiagnosticSnapshot().ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.Quantity);var i=new SocialWorldInput(new("request:gift"),SocialWorldAction.DispatchGift,Other,Amount:20);var result=s.ManageSocial(i,s.Revision);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);var w=s.DiagnosticSnapshot();Assert.Equal(980,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1020,NewGameWork.Balance(w,Other));Assert.Equal(before,w.ResourceLots.Where(l=>l.Kind=="money").Sum(l=>l.Quantity)+SocialWorld.InTransitCoins(w));Assert.Equal(ResultCode.AlreadyAccepted,s.ManageSocial(i,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.ManageSocial(i with{Amount=21},s.Revision).Code);Assert.Single(SocialWorld.Facts(w,Other,s.PlayerControl));}
 [Theory][InlineData(0)][InlineData(1001)]public void InvalidGiftIsAtomic(long amount){var s=new WorldSession(Start());var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.DispatchGift,amount:amount).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact]public void UnknownRemoteRecipientAndUnconsentingCarrierAreRejected(){var s=new WorldSession(Start());Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.DispatchGift,new("person:shingen"),20).Code);var input=new SocialWorldInput(new("request:carrier"),SocialWorldAction.DispatchGift,Other,Other,20);Assert.Equal(ResultCode.NotAvailable,s.ManageSocial(input,s.Revision).Code);}
 [Fact]public void DonationConsumesActualCoinsButDoesNotCreateServiceOrOwnership(){var s=new WorldSession(Start());var w=s.DiagnosticSnapshot();var temple=SocialWorld.Temple(w,SocialWorld.Site(w,s.PlayerControl)!.Value);var result=Act(s,SocialWorldAction.Donate,temple.Representative,40);Assert.True(result.Code==ResultCode.Accepted,result.VisibleReason);w=s.DiagnosticSnapshot();Assert.Equal(960,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(40,SocialWorld.TempleFunds(w,temple.Site));Assert.Equal(3,SocialWorld.Axes(w,temple.Representative,s.PlayerControl).Affection);Assert.Equal(0,SocialWorld.RenownStrength(w,Other,s.PlayerControl,RenownKind.Benevolence));Assert.DoesNotContain(w.ServiceBonds,b=>b.Subject==temple.Representative);}
 [Theory][InlineData(SocialWorldAction.Protect)][InlineData(SocialWorldAction.IssueBan)]public void RoninCannotIssueAuthorityDocuments(SocialWorldAction action){var s=new WorldSession(Start());var temple=SocialWorld.Temple(s.DiagnosticSnapshot(),SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value);Assert.Equal(ResultCode.NotAvailable,Act(s,action,temple.Representative).Code);}
 [Fact]public void RumorIsUnknownUntilActuallyToldLocally(){var s=new WorldSession(Start());var temple=SocialWorld.Temple(s.DiagnosticSnapshot(),SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value);Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.Donate,temple.Representative,20).Code);var f=SocialWorld.Renown(s.DiagnosticSnapshot(),s.PlayerControl).Single();Assert.Empty(SocialWorld.Renown(s.DiagnosticSnapshot(),Other));Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.TellRumor,Other,reference:new(f.Id)).Code);var heard=SocialWorld.Renown(s.DiagnosticSnapshot(),Other).Single();Assert.Equal(f.Subject,heard.Subject);Assert.Equal(f.OccurredAt,heard.OccurredAt);Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.TellRumor,Other,reference:new(f.Id)).Code);}
 [Fact]public void UnknownRumorCannotBeInvented(){var s=new WorldSession(Start());Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.TellRumor,reference:new("request:unknown")).Code);}
 [Fact]public void RestorePreservesGiftDonationRelationsAndSameFuture(){var s=new WorldSession(Start());Act(s,SocialWorldAction.Visit);Act(s,SocialWorldAction.DispatchGift,amount:20);var temple=SocialWorld.Temple(s.DiagnosticSnapshot(),SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value);Act(s,SocialWorldAction.Donate,temple.Representative,30);var raw=ContractJson.Write(s.DiagnosticSnapshot());var restored=new WorldSession(ContractJson.Read<ContractWorld>(raw));Assert.Equal(raw,ContractJson.Write(restored.DiagnosticSnapshot()));foreach(var x in new[]{s,restored}){var f=SocialWorld.Renown(x.DiagnosticSnapshot(),x.PlayerControl).Single();Assert.Equal(ResultCode.Accepted,Act(x,SocialWorldAction.TellRumor,Other,reference:new(f.Id)).Code);}Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));}
 [Fact]public void DuplicateReceiptIsRejectedOnLoad(){var s=new WorldSession(Start());Act(s,SocialWorldAction.DispatchGift,amount:20);var w=s.DiagnosticSnapshot();var e=w.SocialWorld!.Events.Single(e=>e.Input.Action==SocialWorldAction.ReceiveGift);w.SocialWorld=w.SocialWorld with{Events=[..w.SocialWorld.Events,e with{Input=e.Input with{Id=new("social:forged")}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
 [Fact]public void NullModuleKeepsLegacyBytes(){var w=Start();var bytes=ContractJson.Write(w);Assert.DoesNotContain("SocialWorld",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));}

 [Fact]public void AuthorityDocumentsAreSeparateAndBrokenProtectionBecomesKnownInfamy(){var s=new WorldSession(Start("person:nobunaga"));var site=SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value;var t=SocialWorld.Temple(s.DiagnosticSnapshot(),site);Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.Protect,t.Representative).Code);Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.IssueBan,t.Representative).Code);Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.BreakProtection,t.Representative).Code);var w=s.DiagnosticSnapshot();Assert.True(SocialWorld.RenownStrength(w,t.Representative,s.PlayerControl,RenownKind.Infamy)>0);Assert.Equal(0,SocialWorld.RenownStrength(w,Other,s.PlayerControl,RenownKind.Infamy));Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.Protect,t.Representative).Code);}
 [Fact]public void RefusedIncomingGiftReturnsThroughItsActualNpcCarrier(){var w=Start("created:social-b");w.CommitSequence=1;var sender=new EntityId("created:social-a");var id=new EntityId("request:incoming");SocialWorld.Execute(w,new(id,SocialWorldAction.DispatchGift,Other,sender,20),sender);var s=new WorldSession(w);Assert.Equal(980,NewGameWork.Balance(s.DiagnosticSnapshot(),sender));Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.RefuseGift,sender,reference:id).Code);w=s.DiagnosticSnapshot();Assert.Equal(1000,NewGameWork.Balance(w,sender));Assert.Equal(1000,NewGameWork.Balance(w,Other));Assert.Equal(0,SocialWorld.InTransitCoins(w));}
 [Fact]public void ARecipientCannotReceiveRemotePhysicalContents(){var w=Start("created:social-b");w.CommitSequence=1;var sender=new EntityId("created:social-a");var id=new EntityId("request:incoming-road");SocialWorld.Execute(w,new(id,SocialWorldAction.DispatchGift,Other,sender,20),sender);var s=new WorldSession(w);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-gift","kofu"),s.Revision).Code);NewGameWorldTests.At(s,2);Assert.Equal(ResultCode.NotAvailable,Act(s,SocialWorldAction.ReceiveGift,sender,reference:id).Code);Assert.Equal(20,SocialWorld.InTransitCoins(s.DiagnosticSnapshot()));}
 [Fact]public void RumorStrengthDependsOnObserverAndRegionAndFades(){var s=new WorldSession(Start());var site=SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value;Act(s,SocialWorldAction.Donate,SocialWorld.Temple(s.DiagnosticSnapshot(),site).Representative,20);var w=s.DiagnosticSnapshot();int first=SocialWorld.RenownStrength(w,s.PlayerControl,s.PlayerControl,RenownKind.Benevolence,site);Assert.True(first>0);Assert.Equal(0,SocialWorld.RenownStrength(w,s.PlayerControl,s.PlayerControl,RenownKind.Benevolence,new("site:village")));w.ElapsedSeconds+=2592000;Assert.True(SocialWorld.RenownStrength(w,s.PlayerControl,s.PlayerControl,RenownKind.Benevolence,site)<first);}
 [Fact]public void FutureMoneyCannotPayAnEarlierJourney(){var s=new WorldSession(Start());long at=s.Seconds;long rev=s.Revision;Act(s,SocialWorldAction.DispatchGift,amount:20);var w=s.DiagnosticSnapshot();Assert.Equal(0,SocialWorld.Net(w,NewGameWork.Wallet(s.PlayerControl),at,rev));Assert.Equal(-20,SocialWorld.Net(w,NewGameWork.Wallet(s.PlayerControl)));}
 [Fact]public void NonceCannotBecomeAnUnrelatedCoreCommand(){var s=new WorldSession(Start());var id="request:shared-social-id";Assert.Equal(ResultCode.Accepted,Act(s,SocialWorldAction.Visit,id:id).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(NewGameWorld.Inspect(s.DiagnosticSnapshot(),id),s.Revision).Code);}
 [Fact]public void NpcUsesTheSameSocialRulesAtCalendarBoundariesAndRestore(){var a=new WorldSession(Start());Act(a,SocialWorldAction.Visit);var b=new WorldSession(ContractJson.Copy(a.DiagnosticSnapshot()));foreach(var s in new[]{a,b})NewGameWorldTests.At(s,86400);var wa=a.DiagnosticSnapshot();Assert.Contains(wa.SocialWorld!.Events,e=>e.Actor!=a.PlayerControl&&e.Input.Action==SocialWorldAction.Visit);Assert.Equal(ContractJson.Write(wa),ContractJson.Write(b.DiagnosticSnapshot()));}
 [Theory][InlineData(DevelopmentSkill.Tactics,RenownKind.Valor)][InlineData(DevelopmentSkill.Etiquette,RenownKind.Culture)]public void TrainingReputationHasAnActualAwardSourceAndIsNotBattleMerit(DevelopmentSkill skill,RenownKind kind){var old=Start();var d=old.NewGame!;var w=NewGameWorld.Create(d.Start,d.Registered,d.Selected.Value,d.Seed,developmentPolicy:CharacterDevelopment.Policy,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy);var s=new WorldSession(w);var i=CharacterDevelopment.Practice(s.DiagnosticSnapshot(),"request:reputation-study",skill);Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);NewGameWorldTests.At(s,i.EffectiveAt+i.WorkSeconds+i.DeliverySeconds+1);var facts=SocialWorld.Renown(s.DiagnosticSnapshot(),s.PlayerControl);Assert.Contains(facts,f=>f.Kind==kind&&f.Source.Contains("合戦の戦功とは区別"));Assert.Empty(SocialWorld.Renown(s.DiagnosticSnapshot(),Other));}

 [Fact]public void CalendarPartitionDoesNotChangeNpcSocialActions(){var a=new WorldSession(Start());Act(a,SocialWorldAction.Visit);var b=new WorldSession(ContractJson.Copy(a.DiagnosticSnapshot()));NewGameWorldTests.At(a,172800);foreach(long at in new long[]{43200,86400,129600,172800})NewGameWorldTests.At(b,at);var x=a.DiagnosticSnapshot().SocialWorld!.Events.Select(e=>e with{Revision=0}).ToArray();var y=b.DiagnosticSnapshot().SocialWorld!.Events.Select(e=>e with{Revision=0}).ToArray();Assert.Equal(ContractJson.Write(x),ContractJson.Write(y));}
 [Fact]public void PendingPhysicalGiftRestoresBeforeItsRefusalAndNpcReturn(){var w=Start("created:social-b");w.CommitSequence=1;var sender=new EntityId("created:social-a");var id=new EntityId("request:pending-gift-save");SocialWorld.Execute(w,new(id,SocialWorldAction.DispatchGift,Other,sender,20),sender);var a=new WorldSession(w);var bytes=ContractJson.Write(a.DiagnosticSnapshot());var b=new WorldSession(ContractJson.Read<ContractWorld>(bytes));foreach(var x in new[]{a,b})Assert.Equal(ResultCode.Accepted,Act(x,SocialWorldAction.RefuseGift,sender,reference:id).Code);Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(1000,NewGameWork.Balance(b.DiagnosticSnapshot(),sender));}
 [Theory][InlineData(true)][InlineData(false)]public void FamilyFactsRequireActualImplementationAndAreNotPublicGossip(bool marriage){var records=new[]{NewGameWorldTests.Officer("created:social-a") with{InitialMaritalStatus=InitialMaritalStatus.Unmarried},NewGameWorldTests.Officer("created:social-b") with{InitialMaritalStatus=InitialMaritalStatus.Unmarried},NewGameWorldTests.Officer("created:social-third")};var setup=NewGameWorldTests.Setup(records);ContractWorld Build(ulong seed)=>NewGameWorld.Create(setup.World,setup.Registered,records[0].Id,seed,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,developmentPolicy:CharacterDevelopment.Policy,socialPolicy:CharacterRelations.Policy,adoptionPolicy:AdultAdoption.Policy,marriagePolicy:AdultMarriage.Policy);ulong seed=1;for(;seed<100;seed++){var c=Build(seed);if(CharacterRelations.DiagnosticTrait(c,Other,SocialTrait.Duty)+CharacterRelations.DiagnosticTrait(c,Other,SocialTrait.Affection)>=80)break;}var session=new WorldSession(Build(seed));var root=new EntityId("request:family-social");CommandResult r=marriage?session.DecideMarriage(new(root,MarriageAction.Propose,Other),session.PlayerControl,session.Revision):session.DecideAdoption(new(root,AdoptionAction.Propose,Other),session.PlayerControl,session.Revision);Assert.Equal(ResultCode.Accepted,r.Code);Assert.DoesNotContain(SocialWorld.Facts(session.DiagnosticSnapshot(),session.PlayerControl,Other),f=>f.Source.StartsWith("kinship:"));NewGameWorldTests.At(session,1);r=marriage?session.DecideMarriage(new(new("request:family-implement"),MarriageAction.Implement,Original:root),session.PlayerControl,session.Revision):session.DecideAdoption(new(new("request:family-implement"),AdoptionAction.Implement,Original:root),session.PlayerControl,session.Revision);Assert.Equal(ResultCode.Accepted,r.Code);var w2=session.DiagnosticSnapshot();Assert.Single(SocialWorld.Facts(w2,session.PlayerControl,Other),f=>f.Source.StartsWith("kinship:"));Assert.DoesNotContain(SocialWorld.Facts(w2,new("created:social-third"),Other),f=>f.Source.StartsWith("kinship:"));}

 [Fact]public void AnActualNpcCourierTravelsAloneAndReportsOnlyAfterReturningWithSaveRestore(){
  var a=NewGameWorldTests.Officer("created:courier-owner");var carrier=NewGameWorldTests.Officer("created:courier-agent");var recipient=NewGameWorldTests.Officer("created:courier-recipient");var setup=NewGameWorldTests.Setup([a,carrier,recipient]);
  ContractWorld Build()=>NewGameWorld.Create(setup.World,setup.Registered,a.Id,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy);
  var s=new WorldSession(Build());var npc=new EntityId(carrier.Id);var target=new EntityId(recipient.Id);
  var agreed=s.ManageCompanion(new(new("request:courier-agree"),npc,CompanionAction.Agree,20),s.PlayerControl,s.Revision);Assert.True(agreed.Code==ResultCode.Accepted,agreed.VisibleReason);
  Assert.Equal(ResultCode.Accepted,s.ManageSocial(new(new("request:courier-meeting"),SocialWorldAction.Visit,target),s.Revision).Code);
  var travel=s.ManageCompanion(new(new("request:courier-owner-leaves"),npc,CompanionAction.TravelTogether,Destination:"fork"),s.PlayerControl,s.Revision);Assert.True(travel.Code==ResultCode.Accepted,travel.VisibleReason);NewGameWorldTests.At(s,2);long end=s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt);NewGameWorldTests.At(s,end+2);
  var id=new EntityId("request:independent-courier-gift");var gift=new SocialWorldInput(id,SocialWorldAction.DispatchGift,target,npc,20);var sent=s.ManageSocial(gift,s.Revision);Assert.True(sent.Code==ResultCode.Accepted,sent.VisibleReason);
  var w=s.DiagnosticSnapshot();var entry=w.SocialWorld!.Events.Single(e=>e.Input.Id==id);Assert.NotNull(entry.GiftTerms!.Movement);Assert.Contains(w.Requests,r=>r.Id==entry.GiftTerms.Movement!.RequestId);Assert.Equal(RegionalCampaign.Site("fork"),w.Locations.Single(l=>l.Actor==s.PlayerControl).Site);
  var move=entry.GiftTerms.Movement!;NewGameWorldTests.At(s,move.EffectiveAt+move.DeliverySeconds+move.WorkSeconds);
  w=s.DiagnosticSnapshot();Assert.Contains(w.SocialWorld!.Events,e=>e.Input.Reference==id&&e.Input.Action==SocialWorldAction.ReceiveGift);Assert.Equal("配送先の結果はまだ未確認",SocialWorld.Gifts(w,s.PlayerControl).Single(g=>g.Id==id).Phase);
  var back=w.SocialWorld.Events.Single(e=>e.Input.Reference==id&&e.Input.Action==SocialWorldAction.StartCourierReturn).GiftTerms!.Movement!;
  s.SetPaused(true);w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"social-courier-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"courier",w.WorldId).Published);var host=new WorldSessionHost(new(Build()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("courier"),host.Current,host.Current.Revision));
  var restored=host.Current;Assert.Equal(ContractJson.Write(w),ContractJson.Write(restored.DiagnosticSnapshot()));
  foreach(var x in new[]{s,restored})NewGameWorldTests.At(x,back.EffectiveAt+back.DeliverySeconds+back.WorkSeconds+2);
  Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.Equal("受領済み",SocialWorld.Gifts(s.DiagnosticSnapshot(),s.PlayerControl).Single(g=>g.Id==id).Phase);Assert.Equal(RegionalCampaign.Site("fork"),SocialWorld.Site(s.DiagnosticSnapshot(),npc));
 }

 [Fact]public void UnknownRoadClosureStopsTheActualCourierAndReturnsTheSameCoins(){var a=NewGameWorldTests.Officer("created:block-owner");var b=NewGameWorldTests.Officer("created:block-courier");var c=NewGameWorldTests.Officer("created:block-recipient");var setup=NewGameWorldTests.Setup([a,b,c]);var w=NewGameWorld.Create(setup.World,setup.Registered,a.Id,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,voyageRules:VoyageExpense.Standard);var s=new WorldSession(w);var carrier=new EntityId(b.Id);var target=new EntityId(c.Id);Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:block-agree"),carrier,CompanionAction.Agree,20),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ManageSocial(new(new("request:block-meet"),SocialWorldAction.Visit,target),s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ManageCompanion(new(new("request:block-walk"),carrier,CompanionAction.TravelTogether,Destination:"fork"),s.PlayerControl,s.Revision).Code);NewGameWorldTests.At(s,2);NewGameWorldTests.At(s,s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt)+2);w=s.DiagnosticSnapshot();var edge=BranchRoutes.Plan("fork","castle",[],w:w,departureAt:s.Seconds+1)[0];w.Couriers=w.Couriers! with{Conditions=[..w.Couriers.Conditions,..BranchRoutes.GraphEdges(w).Where(e=>e.From=="fork"||e.To=="fork").Select(e=>new RoadCondition(s.Seconds+1,e.Id,true))]};s=new WorldSession(w);long money=NewGameWork.Balance(w,s.PlayerControl);var id=new EntityId("request:block-gift");Assert.Equal(ResultCode.Accepted,s.ManageSocial(new(id,SocialWorldAction.DispatchGift,target,carrier,20),s.Revision).Code);Assert.DoesNotContain(edge,BranchRoutes.KnownBlocked(s.DiagnosticSnapshot(),s.PlayerControl));NewGameWorldTests.At(s,s.Seconds+2);w=s.DiagnosticSnapshot();Assert.Equal(money,NewGameWork.Balance(w,s.PlayerControl));Assert.Contains(w.SocialWorld!.Events,e=>e.Input.Reference==id&&e.Input.Action==SocialWorldAction.CourierBlocked);Assert.Equal("返却済み",SocialWorld.Gifts(w,s.PlayerControl).Single(g=>g.Id==id).Phase);Assert.DoesNotContain(edge,BranchRoutes.KnownBlocked(w,s.PlayerControl));Assert.Contains(edge,BranchRoutes.KnownBlocked(w,carrier));Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Copy(w)).DiagnosticSnapshot()));}

 [Fact]public void RepeatingDonationsOnTheSameDayCannotMultiplyReputation(){var s=new WorldSession(Start());var site=SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value;var temple=SocialWorld.Temple(s.DiagnosticSnapshot(),site);Act(s,SocialWorldAction.Donate,temple.Representative,20);int strength=SocialWorld.RenownStrength(s.DiagnosticSnapshot(),s.PlayerControl,s.PlayerControl,RenownKind.Benevolence);Act(s,SocialWorldAction.Donate,temple.Representative,20);Assert.Equal(strength,SocialWorld.RenownStrength(s.DiagnosticSnapshot(),s.PlayerControl,s.PlayerControl,RenownKind.Benevolence));Assert.Equal(960,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}

 [Fact]public void UnopenedInvitationDoesNotMakeThePersonPhysicallyUnavailable(){var s=new WorldSession(NpcJudgmentTests.Start());NewGameWorldTests.At(s,10);var w=s.DiagnosticSnapshot();var t=w.Tasks.Single(t=>t.Executor==s.PlayerControl&&t.Issuer!=s.PlayerControl);Assert.Equal(AgreementPhase.AwaitingRecognition,t.Agreement);Assert.NotNull(SocialWorld.Site(w,s.PlayerControl));Assert.Equal(ResultCode.Accepted,s.ManageSocial(new(new("request:meet-before-opening"),SocialWorldAction.Visit,t.Issuer),s.Revision).Code);Assert.Equal(AgreementPhase.AwaitingRecognition,s.DiagnosticSnapshot().Tasks.Single(x=>x.Id==t.Id).Agreement);}
}
